public class Turret : MonoBehaviour {
    [SerializeField] Rigidbody rb;
    [SerializeField] float turnRate = 1f;
    void Awake() => rb.interpolation = RigidbodyInterpolation.Interpolate;
    void FixedUpdate() {                     // fixed step: Time.fixedDeltaTime
        rb.AddTorque(0f, turnRate * Time.fixedDeltaTime, 0f);
        Think();                             // AI/physics decisions belong here
    }
    void Update() {                          // variable render tick, once per frame
        AimAtCrosshair();                    // input and presentation only
    }
}

