protected override void Update(GameTime gameTime) {
    var dt = (float)gameTime.ElapsedGameTime.TotalSeconds;  // == TargetElapsedTime
    PollInput();
    world.Step(dt);                                        // fixed-step simulation
}
protected override void Draw(GameTime gameTime) {
    GraphicsDevice.Clear(Color.Black);
    spriteBatch.Begin();
    world.Render(spriteBatch);                             // current state only
    spriteBatch.End();
}

var sw = Stopwatch.StartNew();
var prev = sw.Elapsed;
var dt = TimeSpan.FromSeconds(1.0 / 60.0);
var lag = TimeSpan.Zero;
while (running) {
    var now = sw.Elapsed;
    lag += now - prev; prev = now;
    if (lag > TimeSpan.FromMilliseconds(250)) lag = TimeSpan.FromMilliseconds(250);
    while (lag >= dt) { world.Step(dt.TotalSeconds); lag -= dt; }
    Thread.Sleep(1);                     // yield; Stopwatch is re-read next turn
}
